    public function __construct(private PDO $pdo,private MunicipalRequirementRegistry $matrices){}

    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function assess(string$organisationId,string$userId,string$role,string$projectId,string$matrixId,array$input):array
    {
        $this->member($organisationId,$userId);$project=$this->project($organisationId,$projectId);$matrix=$this->matrices->get($organisationId,$matrixId);if($matrix['municipalityKey']!==$this->key($project['municipality']))throw new MunicipalReadinessException('municipal_matrix_project_mismatch');$facts=$this->facts($input);$complexity=$this->complexity($facts);$team=$this->team($organisationId,$projectId);$routing=$this->routing($project,$facts,$complexity,$team);$evidence=$this->liveEvidence($organisationId,$projectId,$facts);$checks=$this->checks($matrix['requirements'],$project,$facts,$routing,$evidence);$categories=$this->categories($checks);$applicable=array_filter($checks,static fn(array$c):bool=>$c['status']!=='not_applicable');$complete=array_filter($applicable,static fn(array$c):bool=>$c['status']==='complete');$score=$applicable===[]?100:(int)round(count($complete)*100/count($applicable));$blockers=array_values(array_map(static fn(array$c):string=>$c['label'].' ('.$c['owner'].')',array_filter($applicable,static fn(array$c):bool=>$c['status']==='missing')));$reviews=array_values(array_map(static fn(array$c):string=>$c['label'].' requires '.$c['owner'].' review',array_filter($applicable,static fn(array$c):bool=>$c['status']==='requires_professional_review')));$ready=$blockers===[]&&$reviews===[];$missingDocs=array_values(array_map(static fn(array$c):string=>$c['label'],array_filter($checks,static fn(array$c):bool=>$c['status']==='missing'&&in_array($c['category'],['drawing_register','supporting_documents','client_authority'],true))));$signoffs=array_values(array_map(static fn(array$c):string=>$c['label'],array_filter($checks,static fn(array$c):bool=>$c['category']==='professional_signoffs'&&$c['status']!=='complete')));$recommendations=$this->recommendations($routing,$blockers,$reviews,$matrix);$pack=$this->evidencePack($project,$matrix,$routing,$checks,$evidence,$ready);$id=Identifier::generate();
        $snapshot=['project'=>['id'=>$projectId,'projectCode'=>$project['projectCode'],'projectName'=>$project['projectName'],'clientName'=>$project['clientName'],'municipality'=>$project['municipality'],'propertyReference'=>$project['propertyReference'],'propertyUse'=>$project['propertyUse'],'phase'=>$project['phase']],'matrix'=>['id'=>$matrix['id'],'version'=>$matrix['version'],'status'=>$matrix['status'],'sourceReference'=>$matrix['sourceReference'],'effectiveDate'=>$matrix['effectiveDate'],'payloadSha256'=>$matrix['payloadSha256']],'complexity'=>$complexity,'professionalRouting'=>$routing,'categories'=>$categories,'checks'=>$checks,'overallScore'=>$score,'readyForProfessionalSubmissionReview'=>$ready,'professionalApprovalEligible'=>$ready&&$matrix['status']==='verified','blockers'=>$blockers,'professionalReviews'=>$reviews,'missingDocuments'=>$missingDocs,'requiredHumanSignoffs'=>$signoffs,'evidencePack'=>$pack,'recommendations'=>$recommendations,'assumptions'=>['Scope triggers are explicit human inputs.','Document and ToolRun evidence is limited to records currently stored in this organisation and project.','The assessment is advisory and does not represent statutory approval, certification or municipal lodgement.'],'confidence'=>$this->confidence($project,$facts,$matrix,$evidence),'municipalSubmissionCreated'=>false,'advisoryOnly'=>true];$json=$this->json($snapshot);$sha=hash('sha256',$json);
        $this->pdo->beginTransaction();try{$this->pdo->prepare('INSERT INTO municipal_readiness_assessments(id,organisation_id,project_id,matrix_version_id,complexity,overall_score,ready_for_professional_review,assessment_snapshot,snapshot_sha256,created_by) VALUES(UNHEX(:id),UNHEX(:organisation_id),UNHEX(:project_id),UNHEX(:matrix_id),:complexity,:score,:ready,:snapshot,:sha,UNHEX(:user_id))')->execute(['id'=>$id,'organisation_id'=>$organisationId,'project_id'=>$projectId,'matrix_id'=>$matrixId,'complexity'=>$complexity['level'],'score'=>$score,'ready'=>$ready?1:0,'snapshot'=>$json,'sha'=>$sha,'user_id'=>$userId]);$recordId=(new ProjectRecordService($this->pdo))->issue(new ProjectContext($organisationId,$userId,$projectId,$role),ProjectPhase::MunicipalSubmission,'municipal_readiness','municipal_submission_readiness','Municipal submission readiness assessment','pending_review',['assessmentId'=>$id,'snapshotSha256'=>$sha,'overallScore'=>$score,'complexity'=>$complexity['level'],'readyForProfessionalSubmissionReview'=>$ready,'matrix'=>$snapshot['matrix'],'blockers'=>$blockers],['required'=>true,'professionalApproved'=>false]);$this->pdo->prepare('UPDATE municipal_readiness_assessments SET project_record_id=UNHEX(:record_id) WHERE id=UNHEX(:id)')->execute(['record_id'=>$recordId,'id'=>$id]);$this->routeInbox($organisationId,$projectId,$id,$routing,$blockers);(new AuditService($this->pdo))->append($organisationId,$userId,'municipal_readiness.assessed','municipal_readiness_assessment',$id,['projectId'=>$projectId,'matrixVersionId'=>$matrixId,'matrixStatus'=>$matrix['status'],'snapshotSha256'=>$sha,'overallScore'=>$score,'complexity'=>$complexity['level'],'readyForProfessionalSubmissionReview'=>$ready]);$this->pdo->commit();}catch(Throwable$exception){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$exception;}return$this->get($organisationId,$userId,$id);
    }

    /** @return array<string,mixed> */
    public function approveForProfessionalReview(string$o,string$u,string$r,string$id,bool$confirmed,string$reason):array
    {
        if(!in_array($r,['owner','admin','member'],true))throw new MunicipalReadinessException('municipal_readiness_role_denied');$this->member($o,$u);if(!$confirmed)throw new MunicipalReadinessException('municipal_readiness_confirmation_required');$reason=$this->text($reason,500,'municipal_readiness_review_reason_required');$assessment=$this->get($o,$u,$id);if($assessment['matrix']['status']!=='verified')throw new MunicipalReadinessException('verified_municipal_matrix_required');if(!$assessment['readyForProfessionalSubmissionReview'])throw new MunicipalReadinessException('municipal_readiness_blocked');
        $reviewId=Identifier::generate();try{$this->pdo->beginTransaction();$this->pdo->prepare("INSERT INTO municipal_readiness_reviews(id,organisation_id,assessment_id,decision,reason,assessment_sha256,reviewed_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:assessment),'approved_for_professional_submission_review',:reason,:sha,UNHEX(:u))")->execute(['id'=>$reviewId,'o'=>$o,'assessment'=>$id,'reason'=>$reason,'sha'=>$assessment['snapshotSha256'],'u'=>$u]);(new ProjectRecordService($this->pdo))->issue(new ProjectContext($o,$u,$assessment['project']['id'],$r),ProjectPhase::MunicipalSubmission,'municipal_readiness','municipal_submission_review','Professional readiness review approved','approved',['assessmentId'=>$id,'assessmentSha256'=>$assessment['snapshotSha256'],'reviewId'=>$reviewId,'decision'=>'approved_for_professional_submission_review','reason'=>$reason,'municipalApproval'=>false,'submissionCreated'=>false],['required'=>true,'approvedBy'=>$u,'humanApprovalConfirmed'=>true]);(new AuditService($this->pdo))->append($o,$u,'municipal_readiness.professional_review_approved','municipal_readiness_assessment',$id,['reviewId'=>$reviewId,'assessmentSha256'=>$assessment['snapshotSha256'],'reason'=>$reason,'municipalApproval'=>false]);$this->pdo->commit();}catch(PDOException$exception){if($this->pdo->inTransaction())$this->pdo->rollBack();if((string)$exception->getCode()==='23000')throw new MunicipalReadinessException('municipal_readiness_already_reviewed');throw$exception;}catch(Throwable$exception){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$exception;}return$this->get($o,$u,$id);
    }

    /** @return array<string,mixed> */
    public function get(string$o,string$u,string$id):array
    {
        $this->member($o,$u);if(preg_match('/\A[a-f0-9]{32}\z/i',$id)!==1)throw new MunicipalReadinessException('municipal_readiness_not_found');$s=$this->pdo->prepare("SELECT LOWER(HEX(a.id)) id,LOWER(HEX(a.project_record_id)) project_record_id,a.assessment_snapshot,a.snapshot_sha256,DATE_FORMAT(a.created_at,'%Y-%m-%dT%H:%i:%s.%fZ') created_at,LOWER(HEX(r.id)) review_id,r.decision review_decision,r.reason review_reason,LOWER(HEX(r.reviewed_by)) reviewed_by,DATE_FORMAT(r.reviewed_at,'%Y-%m-%dT%H:%i:%s.%fZ') reviewed_at FROM municipal_readiness_assessments a LEFT JOIN municipal_readiness_reviews r ON r.assessment_id=a.id AND r.organisation_id=a.organisation_id WHERE a.id=UNHEX(:id) AND a.organisation_id=UNHEX(:o)");$s->execute(['id'=>$id,'o'=>$o]);$row=$s->fetch();if(!is_array($row))throw new MunicipalReadinessException('municipal_readiness_not_found');$snapshot=json_decode((string)$row['assessment_snapshot'],true,128,JSON_THROW_ON_ERROR);$sha=hash('sha256',$this->json($snapshot));if(!hash_equals((string)$row['snapshot_sha256'],$sha))throw new MunicipalReadinessException('municipal_readiness_integrity_failed');return['id'=>(string)$row['id'],'snapshotSha256'=>(string)$row['snapshot_sha256'],'projectRecordId'=>$row['project_record_id'],'createdAt'=>(string)$row['created_at'],'professionalReview'=>$row['review_id']===null?null:['id'=>$row['review_id'],'decision'=>$row['review_decision'],'reason'=>$row['review_reason'],'reviewedBy'=>$row['reviewed_by'],'reviewedAt'=>$row['reviewed_at']]]+$snapshot;
    }

    /** @return list<array<string,mixed>> */
    public function list(string$o,string$u,string$projectId):array{$this->member($o,$u);$this->project($o,$projectId);$s=$this->pdo->prepare('SELECT LOWER(HEX(id)) FROM municipal_readiness_assessments WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) ORDER BY created_at DESC,id DESC');$s->execute(['o'=>$o,'p'=>$projectId]);return array_map(fn(string$id):array=>$this->get($o,$u,$id),$s->fetchAll(PDO::FETCH_COLUMN));}

    /** @return array<string,string> */
    private function project(string$o,string$p):array{if(preg_match('/\A[a-f0-9]{32}\z/i',$p)!==1)throw new MunicipalReadinessException('municipal_project_not_found');$s=$this->pdo->prepare('SELECT project_code projectCode,project_name projectName,client_name clientName,municipality,property_reference propertyReference,property_use propertyUse,land_use_notes landUseNotes,lead_professional_role leadProfessionalRole,current_phase phase FROM projects WHERE id=UNHEX(:p) AND organisation_id=UNHEX(:o)');$s->execute(['p'=>$p,'o'=>$o]);$row=$s->fetch();if(!is_array($row))throw new MunicipalReadinessException('municipal_project_not_found');return$row;}
    /** @param array<string,mixed> $i @return array<string,mixed> */
    private function facts(array$i):array{$occupancy=$i['occupancyType']??null;if(!in_array($occupancy,['single_residential','multi_residential','commercial','public_assembly','mixed_use'],true))throw new MunicipalReadinessException('invalid_occupancy_type');$facts=['occupancyType'=>$occupancy];foreach(['changesLoadBearing','changesDrainageOrStormwater','publicAccessOrAssembly','envelopeEnergyImpact','zoningKnown','coverageOrParkingRisk','boundaryOrServitudeUnclear','heritagePotential','environmentalSensitivity','trafficImpact','nbrAdvisoryReviewed','clientAuthorityConfirmed']as$key){if(!is_bool($i[$key]??null))throw new MunicipalReadinessException('invalid_municipal_scope_facts');$facts[$key]=$i[$key];}$value=$i['estimatedConstructionValueZar']??null;if(!is_int($value)&&!is_float($value))throw new MunicipalReadinessException('invalid_construction_value');$facts['estimatedConstructionValueZar']=(float)$value;$facts['availableSupportingDocuments']=$this->choices($i['availableSupportingDocuments']??[],['title_deed','sg_diagram','zoning_certificate','client_authority','appointment_record','heritage_comment','traffic_comment','environmental_comment']);$facts['professionalSignoffs']=$this->choices($i['professionalSignoffs']??[],self::DISCIPLINES);return$facts;}
    /** @param list<string> $allowed @return list<string> */private function choices(mixed$v,array$allowed):array{if(!is_array($v))throw new MunicipalReadinessException('invalid_municipal_scope_facts');$out=[];foreach($v as$x){if(!is_string($x)||!in_array($x,$allowed,true))throw new MunicipalReadinessException('invalid_municipal_scope_facts');$out[$x]=true;}return array_keys($out);}
    /** @param array<string,mixed> $f @return array{level:string,triggers:list<string>} */
    private function complexity(array$f):array{$t=[];if($f['changesLoadBearing'])$t[]='Load-bearing or structural changes indicated.';if($f['changesDrainageOrStormwater'])$t[]='Drainage, stormwater or services impact indicated.';if($f['publicAccessOrAssembly']||$f['occupancyType']==='public_assembly')$t[]='Public access, assembly or elevated fire-life-safety risk indicated.';if($f['envelopeEnergyImpact'])$t[]='Building envelope or energy impact indicated.';if(!$f['zoningKnown']||$f['coverageOrParkingRisk'])$t[]='Zoning, land-use, coverage or parking risk is unresolved.';if($f['boundaryOrServitudeUnclear'])$t[]='Boundary, SG diagram, servitude or site verification is unresolved.';if($f['heritagePotential'])$t[]='Heritage trigger indicated.';if($f['environmentalSensitivity'])$t[]='Environmental sensitivity trigger indicated.';if($f['trafficImpact'])$t[]='Traffic or access impact trigger indicated.';if($f['estimatedConstructionValueZar']>5000000)$t[]='High project value requires stronger cost and risk coordination.';return['level'=>count($t)>=5?'high':(count($t)>=2?'medium':'low'),'triggers'=>$t];}
    /** @return array<string,array<string,string>> */private function team(string$o,string$p):array{$s=$this->pdo->prepare("SELECT discipline,status,verification_grade FROM project_team_members WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND status IN ('invited','active')");$s->execute(['o'=>$o,'p'=>$p]);$out=[];foreach($s as$row)$out[$this->discipline((string)$row['discipline'])]=['status'=>(string)$row['status'],'verificationGrade'=>(string)$row['verification_grade']];return$out;}
    private function discipline(string$v):string{$v=strtolower(str_replace([' ','-'],'_',$v));return match($v){'structural','structural_engineering'=>'structural_engineer','civil','civil_engineering'=>'civil_engineer','fire','fire_engineering'=>'fire_consultant','energy','sans_10400_xa'=>'energy_consultant','town_planning'=>'town_planner','land_surveying','geomatics'=>'land_surveyor','quantity_surveying','qs'=>'quantity_surveyor','heritage'=>'heritage_practitioner','environmental'=>'environmental_practitioner','traffic'=>'traffic_engineer',default=>$v};}
    /** @param array<string,string> $p @param array<string,mixed> $f @param array{level:string,triggers:list<string>} $c @param array<string,array<string,string>> $team @return list<array<string,mixed>> */
    private function routing(array$p,array$f,array$c,array$team):array{$spec=[['client','required','Client/developer provides authority, property evidence and project intent.'],['lead_professional','required','Lead appointed professional coordinates and approves the readiness review.'],['architect','required','Architect or lead designer owns the architectural drawing package.'],['municipal_coordinator','required','Municipal requirement and evidence-pack coordination is required.'],['structural_engineer',$f['changesLoadBearing']?'required':'not_currently_required',$f['changesLoadBearing']?'Load-bearing or structural work is indicated.':'No structural trigger is captured.'],['civil_engineer',$f['changesDrainageOrStormwater']?'required':'not_currently_required',$f['changesDrainageOrStormwater']?'Drainage, stormwater or services impact is indicated.':'No civil-services trigger is captured.'],['fire_consultant',($f['publicAccessOrAssembly']||$f['occupancyType']==='public_assembly')?'required':'optional',($f['publicAccessOrAssembly']||$f['occupancyType']==='public_assembly')?'Public assembly/access or fire-life-safety risk is indicated.':'No hard fire trigger is captured; professional or municipal review may still request input.'],['energy_consultant',$f['envelopeEnergyImpact']?'required':'not_currently_required',$f['envelopeEnergyImpact']?'Envelope, fenestration or energy impact is indicated.':'No energy-envelope trigger is captured.'],['town_planner',(!$f['zoningKnown']||$f['coverageOrParkingRisk'])?'required':'not_currently_required',(!$f['zoningKnown']||$f['coverageOrParkingRisk'])?'Zoning is unknown or coverage/parking risk is unresolved.':'No current land-use trigger is captured.'],['land_surveyor',$f['boundaryOrServitudeUnclear']?'required':'not_currently_required',$f['boundaryOrServitudeUnclear']?'Boundary, SG diagram, servitude or site verification is unresolved.':'No boundary or servitude trigger is captured.'],['quantity_surveyor',$c['level']==='low'?'not_currently_required':'optional',$c['level']==='low'?'Low complexity does not currently trigger cost-control routing.':'Medium/high complexity makes QS input useful but not automatically mandatory.'],['heritage_practitioner',$f['heritagePotential']?'required':'not_currently_required',$f['heritagePotential']?'Heritage potential is indicated.':'No heritage trigger is captured.'],['environmental_practitioner',$f['environmentalSensitivity']?'required':'not_currently_required',$f['environmentalSensitivity']?'Environmental sensitivity is indicated.':'No environmental trigger is captured.'],['traffic_engineer',$f['trafficImpact']?'required':'not_currently_required',$f['trafficImpact']?'Traffic, parking or access impact is indicated.':'No traffic/access trigger is captured.']];$out=[];foreach($spec as[$d,$status,$reason]){$stored=$team[$d]??null;$base=in_array($d,['client','lead_professional','architect'],true);$appointment=$base?'project_baseline':($stored['status']??'missing');$supervision=$stored!==null&&$stored['verificationGrade']!=='externally_verified'&&$status==='required';$out[]=['discipline'=>$d,'status'=>$status,'reason'=>$reason,'teamStatus'=>$appointment,'professionalApprovalRequired'=>!in_array($d,['client','municipal_coordinator','quantity_surveyor'],true),'supervisingProfessionalRequired'=>$supervision];}return$out;}
    /** @param array<string,mixed> $f @return array<string,mixed> */
    private function liveEvidence(string$o,string$p,array$f):array{$s=$this->pdo->prepare('SELECT d.document_type documentType,r.status,r.issue_purpose issuePurpose FROM controlled_documents d JOIN document_revisions r ON r.id=d.current_revision_id WHERE d.organisation_id=UNHEX(:o) AND d.project_id=UNHEX(:p)');$s->execute(['o'=>$o,'p'=>$p]);$documents=$s->fetchAll();$s=$this->pdo->prepare('SELECT sheet_type sheetType,status,issue_purpose issuePurpose,LOWER(HEX(revision_id)) revisionId FROM drawing_register_entries WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p)');$s->execute(['o'=>$o,'p'=>$p]);$drawings=$s->fetchAll();$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,revision,status,project_facts,professional_confirmed_at,formally_issued_at FROM professional_appointments WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) ORDER BY revision DESC,created_at DESC LIMIT 1");$s->execute(['o'=>$o,'p'=>$p]);$appointment=$s->fetch();if(is_array($appointment))$appointment=['id'=>$appointment['id'],'revision'=>(int)$appointment['revision'],'status'=>$appointment['status'],'projectFacts'=>json_decode((string)$appointment['project_facts'],true,64,JSON_THROW_ON_ERROR),'professionalConfirmed'=>$appointment['professional_confirmed_at']!==null,'formallyIssued'=>$appointment['formally_issued_at']!==null];else$appointment=null;$s=$this->pdo->prepare("SELECT DISTINCT record_type FROM project_records WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND status IN ('approved','issued') ORDER BY record_type");$s->execute(['o'=>$o,'p'=>$p]);$recordTypes=array_values(array_map('strval',$s->fetchAll(PDO::FETCH_COLUMN)));$s=$this->pdo->prepare("SELECT tool_id,LOWER(HEX(id)) id,status,output_payload FROM tool_runs WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND tool_id IN ('fenestration_xa_calculator','r_value_thermal_calculator','sans_forms_checklist_builder','drawing_compliance_precheck') AND status IN ('completed','issued') ORDER BY created_at DESC");$s->execute(['o'=>$o,'p'=>$p]);$compliance=[];foreach($s as$row)if(!isset($compliance[$row['tool_id']]))$compliance[$row['tool_id']]=['id'=>$row['id'],'status'=>$row['status'],'output'=>json_decode((string)$row['output_payload'],true,64,JSON_THROW_ON_ERROR)];return['appointment'=>$appointment,'projectRecordTypes'=>$recordTypes,'documents'=>$documents,'drawings'=>$drawings,'complianceRuns'=>$compliance,'availableSupportingDocuments'=>$f['availableSupportingDocuments'],'professionalSignoffs'=>$f['professionalSignoffs']];}
    /** @param list<array<string,mixed>> $requirements @param array<string,string> $p @param array<string,mixed> $f @param list<array<string,mixed>> $routing @param array<string,mixed> $e @return list<array<string,mixed>> */
    private function checks(array$requirements,array$p,array$f,array$routing,array$e):array{$required=array_values(array_filter($routing,static fn(array$r):bool=>$r['status']==='required'));$teamReady=!array_filter($required,static fn(array$r):bool=>$r['teamStatus']==='missing');$disciplineSignoffs=array_values(array_filter(array_column($required,'discipline'),static fn(string$d):bool=>!in_array($d,['client','municipal_coordinator'],true)));$map=['municipality'=>trim($p['municipality'])!==''?'complete':'missing','property_reference'=>trim($p['propertyReference'])!==''?'complete':'missing','zoning_confirmed'=>$f['zoningKnown']?'complete':'missing','coverage_parking_resolved'=>$f['coverageOrParkingRisk']?'requires_professional_review':'complete','required_team_routed'=>$teamReady?'complete':'missing','nbr_precheck'=>$f['nbrAdvisoryReviewed']?'complete':'requires_professional_review','energy_precheck'=>!$f['envelopeEnergyImpact']?'not_applicable':(isset($e['complianceRuns']['fenestration_xa_calculator'],$e['complianceRuns']['r_value_thermal_calculator'])?'requires_professional_review':'missing'),'title_deed'=>in_array('title_deed',$e['availableSupportingDocuments'],true)?'complete':'missing','sg_diagram'=>in_array('sg_diagram',$e['availableSupportingDocuments'],true)?'complete':'missing','client_authority'=>$f['clientAuthorityConfirmed']||in_array('client_authority',$e['availableSupportingDocuments'],true)?'complete':'missing','lead_signoff'=>in_array('lead_professional',$e['professionalSignoffs'],true)?'complete':'requires_professional_review','discipline_signoffs'=>!array_diff($disciplineSignoffs,$e['professionalSignoffs'])?'complete':'requires_professional_review','municipal_form'=>$this->hasDocument($e['documents'],'municipal_form')?'complete':'missing'];foreach(['site_plan','floor_plan','elevation','section']as$sheet)$map[$sheet]=$this->hasDrawing($e['drawings'],$sheet)?'complete':'missing';$out=[];foreach($requirements as$category)foreach($category['items']as$ite