    /** @param list<array<string,mixed>> $d */private function hasDrawing(array$d,string$sheet):bool{return(bool)array_filter($d,static fn(array$x):bool=>$x['sheetType']===$sheet&&$x['status']==='issued'&&$x['issuePurpose']==='for_municipal_submission');}
    /** @param list<array<string,mixed>> $d */private function hasDocument(array$d,string$type):bool{return(bool)array_filter($d,static fn(array$x):bool=>$x['documentType']===$type&&in_array($x['status'],['approved','issued'],true));}
    private function evidenceSource(string$id):string{return in_array($id,['municipality','property_reference'],true)?'Project Passport':(in_array($id,['site_plan','floor_plan','elevation','section','municipal_form'],true)?'Controlled Documents':(in_array($id,['nbr_precheck','energy_precheck'],true)?'Compliance ToolRuns + human review':'Readiness facts + professional confirmation'));}
    /** @param list<array<string,mixed>> $checks @return array<string,array<string,mixed>> */private function categories(array$checks):array{$out=[];foreach($checks as$c)$out[$c['category']][]=$c;foreach($out as$key=>$items){$a=array_values(array_filter($items,static fn(array$i):bool=>$i['status']!=='not_applicable'));$done=array_values(array_filter($a,static fn(array$i):bool=>$i['status']==='complete'));$out[$key]=['score'=>$a===[]?100:(int)round(count($done)*100/count($a)),'complete'=>count($done),'applicable'=>count($a),'checks'=>$items];}return$out;}
    /** @return list<array<string,mixed>> */private function evidencePack(array$p,array$m,array$r,array$c,array$e,bool$ready):array{$required=count(array_filter($r,static fn(array$x):bool=>$x['status']==='required'));$drawingMissing=(bool)array_filter($c,static fn(array$x):bool=>$x['category']==='drawing_register'&&$x['status']!=='complete');$authorityMissing=(bool)array_filter($c,static fn(array$x):bool=>$x['category']==='client_authority'&&$x['status']!=='complete');return[['id'=>'passport','title'=>'Project Passport baseline','source'=>'Project Passport + ProjectRecord','status'=>'included','linkedRecordTypes'=>$e['projectRecordTypes']],['id'=>'appointment_authority','title'=>'Appointment and client authority','source'=>'Latest Appointment + readiness facts','status'=>$e['appointment']===null||$authorityMissing?'blocked':'included'],['id'=>'municipal_matrix','title'=>'Municipal requirement matrix '.$m['version'],'source'=>$m['sourceReference'],'status'=>$m['status']==='verified'?'included':'professional_review_required'],['id'=>'drawing_register','title'=>'Municipal drawing register','source'=>'Controlled Documents','status'=>$drawingMissing?'blocked':'included'],['id'=>'professional_routing','title'=>"Professional routing table ($required required disciplines)",'source'=>'Trigger-based BEP router','status'=>'included'],['id'=>'signoff_bundle','title'=>'Professional sign-off bundle','source'=>'Required appointed professionals','status'=>$ready?'included':'placeholder']];}
    /** @return list<array<string,mixed>> */private function recommendations(array$r,array$b,array$reviews,array$m):array{$required=implode(', ',array_column(array_filter($r,static fn(array$x):bool=>$x['status']==='required'),'discipline'));$out=[];if($b!==[])$out[]=['id'=>'clear_blockers','title'=>'Clear readiness blockers','rationale'=>implode(' | ',array_slice($b,0,5)),'requiresHumanApproval'=>false];$out[]=['id'=>'route_team','title'=>'Route only triggered professionals','rationale'=>'Required disciplines: '.$required.'. Excluded disciplines remain out until a trigger changes.','requiresHumanApproval'=>false];if($reviews!==[])$out[]=['id'=>'professional_review','title'=>'Obtain appointed professional review','rationale'=>implode(' | ',array_slice($reviews,0,5)),'requiresHumanApproval'=>true];if($m['status']!=='verified')$out[]=['id'=>'verify_matrix','title'=>'Verify current municipality requirements','rationale'=>'The selected matrix is review-required and cannot support professional readiness approval.','requiresHumanApproval'=>true];return$out;}
    /** @param array<string,string> $p @param array<string,mixed> $f @param array<string,mixed> $m @param array<string,mixed> $e */private function confidence(array$p,array$f,array$m,array$e):array{$signals=4+($m['status']==='verified'?2:0)+min(2,count($e['complianceRuns']));return['level'=>$signals>=7?'high':($signals>=5?'medium':'low'),'basis'=>['Project Passport fields read from MariaDB','Scope triggers explicitly supplied by a human','Controlled document register queried','Municipal matrix status: '.$m['status'],'Compliance evidence runs: '.count($e['complianceRuns'])]];}
    /** @param list<array<string,mixed>> $routing @param list<string> $blockers */private function routeInbox(string$o,string$p,string$assessmentId,array$routing,array$blockers):void{foreach($routing as$route)if($route['status']==='required'&&$route['teamStatus']==='missing')$this->inboxOnce($o,$p,'municipal_readiness_professional_required',(string)$route['discipline'],'Municipal readiness input required: '.str_replace('_',' ',(string)$route['discipline']),(string)$route['reason'],'high',['assessmentId'=>$assessmentId,'discipline'=>$route['discipline']]);if($blockers!==[])$this->inboxOnce($o,$p,'municipal_readiness_submission_blocked','lead_professional','Municipal submission readiness is blocked',implode(' | ',array_slice($blockers,0,8)),'high',['assessmentId'=>$assessmentId,'blockerCount'=>count($blockers)]);}
    /** @param array<string,mixed> $payload */private function inboxOnce(string$o,string$p,string$event,string$role,string$title,string$detail,string$priority,array$payload):void{$s=$this->pdo->prepare("SELECT 1 FROM inbox_items WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND event_type=:event AND assigned_role=:role AND status IN ('open','read') LIMIT 1");$s->execute(['o'=>$o,'p'=>$p,'event'=>$event,'role'=>$role]);if($s->fetchColumn()!==false)return;$json=$this->json($payload);$this->pdo->prepare('INSERT INTO workflow_events(id,organisation_id,project_id,event_type,priority,source_module,payload) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),:event,:priority,\'municipal_readiness\',:payload)')->execute(['id'=>Identifier::generate(),'o'=>$o,'p'=>$p,'event'=>$event,'priority'=>$priority,'payload'=>$json]);$this->pdo->prepare("INSERT INTO inbox_items(id,organisation_id,project_id,assigned_role,event_type,title,detail,priority,status,payload) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),:role,:event,:title,:detail,:priority,'open',:payload)")->execute(['id'=>Identifier::generate(),'o'=>$o,'p'=>$p,'role'=>$role,'event'=>$event,'title'=>$title,'detail'=>$detail,'priority'=>$priority,'payload'=>$json]);}
    private function member(string$o,string$u):void{$s=$this->pdo->prepare("SELECT 1 FROM organisation_memberships WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u) AND status='active'");$s->execute(['o'=>$o,'u'=>$u]);if($s->fetchColumn()===false)throw new MunicipalReadinessException('municipal_readiness_permission_denied');}
    private function key(string$v):string{return strtolower(trim((string)preg_replace('/[^a-z0-9]+/i','-',$v),'-'));}
    private function text(mixed$v,int$m,string$e):string{$v=is_string($v)?trim($v):'';if($v===''||mb_strlen($v)>$m)throw new MunicipalReadinessException($e);return$v;}
    /** @param array<mixed> $v */private function json(array$v):string{return json_encode($v,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_PRESERVE_ZERO_FRACTION);}
}
